/*
 * qjs_opcodes.h - QuickJS opcode definitions (standalone, no QuickJS deps)
 *
 * This is a clean re-implementation of quickjs-opcode.h, providing:
 *   - OpFmt: operand format enum
 *   - qjs_op_info_t: per-opcode info (name, size, pop, push, fmt)
 *   - two opcode tables: stock QuickJS ("vanilla") and Frida's fork
 *
 * The tables and the opcode name enum are generated by
 * tools/gen_opcodes.sh - see src/qjs_opcodes_*.inc.
 *
 * Part of the JARONA decompiler.
 */
#ifndef QJS_OPCODES_H
#define QJS_OPCODES_H

#include <stdint.h>

/* =========================================================
 * Operand format
 * ========================================================= */
typedef enum {
    QJS_FMT_none,
    QJS_FMT_none_int,
    QJS_FMT_none_loc,
    QJS_FMT_none_arg,
    QJS_FMT_none_var_ref,
    QJS_FMT_u8,
    QJS_FMT_i8,
    QJS_FMT_loc8,
    QJS_FMT_const8,
    QJS_FMT_label8,
    QJS_FMT_u16,
    QJS_FMT_i16,
    QJS_FMT_label16,
    QJS_FMT_npop,
    QJS_FMT_npopx,
    QJS_FMT_npop_u16,
    QJS_FMT_loc,
    QJS_FMT_arg,
    QJS_FMT_var_ref,
    QJS_FMT_u32,
    QJS_FMT_i32,
    QJS_FMT_const,
    QJS_FMT_label,
    QJS_FMT_atom,
    QJS_FMT_atom_u8,
    QJS_FMT_atom_u16,
    QJS_FMT_atom_label_u8,
    QJS_FMT_atom_label_u16,
    QJS_FMT_label_u16,
} qjs_op_fmt_t;

/* =========================================================
 * Opcode info record
 * ========================================================= */
typedef struct {
    const char *name;
    uint8_t     size;
    int8_t      n_pop;       /* -1 = variable */
    int8_t      n_push;      /* -1 = variable */
    qjs_op_fmt_t fmt;
} qjs_op_info_t;

/* =========================================================
 * QuickJS dialect
 *
 * vanilla: stock QuickJS.  The bytecode opcode space is
 *          0x00..0xB5 base opcodes plus 0xB6..0xF7 short opcodes.
 * frida:   Frida's fork.  Its opcode space also contains the 19
 *          "temporary" (phase 1) opcodes at 0xB6..0xC8, which shifts
 *          every short opcode up by 19 (they start at 0xC9).
 * ========================================================= */
typedef enum {
    QJS_MODE_AUTO = 0,   /* detect automatically */
    QJS_MODE_VANILLA,    /* stock QuickJS */
    QJS_MODE_FRIDA       /* Frida QuickJS fork */
} qjs_op_mode_t;

/* Number of opcode slots in the vanilla table (one per byte value). */
#define QJS_OP_TABLE_SIZE     256
/* Number of opcode slots in the frida table (0x00 .. 0x10A). */
#define QJS_FRIDA_TABLE_SIZE  267
/* The temporary opcodes of the frida dialect occupy 0xB6 .. 0xC8. */
#define QJS_TEMP_OPCODE_COUNT 19
#define QJS_TEMP_OPCODE_FIRST 0xB6
#define QJS_TEMP_OPCODE_LAST  0xC8

/* Opcode name constants - values are the vanilla opcode byte values. */
#include "qjs_opcodes_enum.inc"

/* =========================================================
 * Opcode tables
 * ========================================================= */
extern const qjs_op_info_t qjs_op_info_vanilla[QJS_OP_TABLE_SIZE];
extern const qjs_op_info_t qjs_op_info_frida[QJS_FRIDA_TABLE_SIZE];

/* Number of valid opcodes of the vanilla dialect. */
#define QJS_VANILLA_OP_COUNT ((int)qjs_op_count)
/* Number of valid opcodes of the frida dialect. */
#define QJS_FRIDA_OP_COUNT   QJS_FRIDA_TABLE_SIZE

/* =========================================================
 * API
 * ========================================================= */

/*
 * Return the description of an opcode byte in the given dialect.
 * Never returns NULL: unknown bytes map to a static "invalid" entry
 * whose size is 0.
 */
const qjs_op_info_t *qjs_get_op_info(uint8_t op, qjs_op_mode_t mode);

/*
 * Human readable name of a dialect ("vanilla", "frida", "auto").
 */
const char *qjs_mode_name(qjs_op_mode_t mode);

/*
 * Guess the dialect of a byte code body by walking it with both tables.
 * Never returns QJS_MODE_AUTO.
 */
qjs_op_mode_t qjs_detect_op_mode(const uint8_t *bc, uint32_t bc_len,
                                  int big_endian);

/*
 * Process wide default dialect, used when the caller does not want to
 * auto-detect.  Defaults to QJS_MODE_AUTO.
 */
void         qjs_set_default_mode(qjs_op_mode_t mode);
qjs_op_mode_t qjs_get_default_mode(void);

#endif /* QJS_OPCODES_H */
